frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {  // Only show when submitted
            frm.add_custom_button('Send via WhatsApp', () => {

                frappe.call({
                    method: 'erpnext.accounts.doctype.sales_invoice.sales_invoice.send_invoice_whatsapp',
                    args: {
                      invoice_name: frm.doc.name

                    },
