frappe.ui.form.on('Purchase Receipt', {
  master_rate: function (frm) {
    const rate = flt(frm.doc.master_rate);
    frm.doc.items.forEach(row => {
      row.rate = rate;
      row.amount = flt(row.qty) * rate;
    });
    frm.refresh_field('items');
    frm.script_manager.trigger("calculate_taxes_and_totals");
  }
});

frappe.ui.form.on('Purchase Receipt', {
  refresh(frm) {

    frm.add_custom_button('Upload Items from Excel', () => {
     if (frm.doc.name.startsWith("new-")) {
        frappe.msgprint("Please save the Purchase Receipt first.");
        return;
      }    
      frappe.prompt([
        {
          fieldname: 'excel_file',
          fieldtype: 'Attach',
          label: 'Upload Excel File',
          reqd: 1
        }
      ],
      (values) => {
        frappe.show_progress('Importing Excel', 0, 100, 'In Progress...');
        frappe.call({
          method: "erpnext.stock.doctype.purchase_receipt.purchase_receipt.import_items_from_excel",
          args: {
            docname: frm.doc.name,
            file_url: values.excel_file
          },
          callback: function(r) {
            frappe.hide_progress(); // hide when done
            if (r.message) {
              frappe.msgprint(`✅ Imported ${r.message.success_count} rows successfully`);
              frm.reload_doc();
            }
          }
        });
      },
      'Upload Excel for Items',
      'Import');
    });
  }
});

