frappe.ui.form.on('Update Stock Item', {
  items_add: calculate_totals,
  items_remove: calculate_totals,
  items_on_form_rendered: calculate_totals,
  validate: calculate_totals
});

frappe.ui.form.on('Update Stock Item', {
                rate: calculate_totals
});

function calculate_totals(frm) {
                let total_qty = 0;
                let total_amount = 0;

                (frm.doc.items || []).forEach(row => {
                    total_qty += row.qty || 0;
                    total_amount += row.amount || (row.qty * row.rate) || 0;
                });

                frm.set_value("total_qty", total_qty);
                frm.set_value("total_amount", total_amount);
}

